/bin/bash -lc "node - <<'NODE'
const url = 'http://localhost:3107/'
async function getMetadata() {
  const html = await fetch(url).then(r => r.text())
  const aside = html.match(/<div hidden id=\"S:0\"><aside>(.*?)<\\/aside>/)?.[1]
  const text = aside?.replace(/<"'!--.*?-->/g, '"'')
  return {nav: html.includes('<nav><a href=\"/\">Operations</a></nav>'), text}
}
const first = await getMetadata()
await new Promise(resolve => setTimeout(resolve, 20))
const second = await getMetadata()
console.log(JSON.stringify({first, second, distinct: first.text "'!== second.text}, null, 2))
if (!first.nav || !second.nav || !first.text || !second.text || first.text === second.text) process.exitCode = 1
